import zipfile
import xml.etree.ElementTree as ET

NS = {
    'm': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'
}

z = zipfile.ZipFile('budget.xlsx')
print("=== Files in archive ===")
for n in z.namelist():
    print(" ", n)

# Shared strings
shared = []
if 'xl/sharedStrings.xml' in z.namelist():
    root = ET.fromstring(z.read('xl/sharedStrings.xml'))
    for si in root.findall('m:si', NS):
        texts = [t.text or '' for t in si.findall('.//m:t', NS)]
        shared.append(''.join(texts))

# Workbook -> sheet relation
wb = ET.fromstring(z.read('xl/workbook.xml'))
rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
rid_to_target = {}
for rel in rels.findall('{http://schemas.openxmlformats.org/package/2006/relationships}Relationship'):
    rid_to_target[rel.get('Id')] = rel.get('Target')

for sheet in wb.find('m:sheets', NS):
    rid = sheet.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')
    target = rid_to_target.get(rid)
    print(f"\n=== Sheet: {sheet.get('name')} -> {target} ===")
    sheet_root = ET.fromstring(z.read('xl/' + target.lstrip('/')))
    rows = []
    for row in sheet_root.findall('.//m:sheetData/m:row', NS):
        cells = {}
        for c in row.findall('m:c', NS):
            ref = c.get('r')
            t = c.get('t')
            v = c.find('m:v', NS)
            val = None
            if t == 's' and v is not None:
                val = shared[int(v.text)]
            elif t == 'inlineStr':
                val = ''.join(x.text or '' for x in c.findall('.//m:t', NS))
            elif v is not None:
                val = v.text
            cells[ref] = val
        rows.append(cells)
    # Print grid
    for cells in rows:
        for ref in sorted(cells, key=lambda r: (int(''.join(ch for ch in r if ch.isdigit())), ''.join(ch for ch in r if ch.isalpha()))):
            print(f"{ref}={cells[ref]!r}", end='  ')
        print()
